SELECT  FROM chat_group g
JOIN group_member membership ON membership.group_id = g.id AND membership.user_id = #{userId}
ORDER BY g.created_at, g.id

SELECT  FROM chat_group g
JOIN group_member membership ON membership.group_id = g.id AND membership.user_id = #{userId}
WHERE g.id = #{groupId}

mapper.insert:
INSERT INTO group_member(group_id, user_id, joined_at)
SELECT #{groupId}, id, #{now} FROM app_user WHERE id = #{userId}
ON CONFLICT (group_id, user_id) DO NOTHING
